  cards:[
  ["Contenedores sin gestionar servidores","AWS Fargate (con ECS o EKS)."],
  ["Migrar workloads de Kubernetes existentes","Amazon EKS."],
  ["Rol IAM que usa el código dentro del contenedor","ECS task role."],
  ["Registro privado de imágenes de contenedor","Amazon ECR."],
  ["Varias tareas del mismo servicio en una instancia detrás de un ALB","Dynamic port mapping."]],
